#include <iostream>
using namespace std;
int main() {
    int a = 17, b = 5;
    cout << a + b << " " << a - b << " " << a * b << " " << a / b << " " << a % b << "\n";
    cout << -17 / 5 << " " << -17 % 5 << " " << 17 / -5 << " " << 17 % -5 << "\n";
    cout << (a & b) << " " << (a | b) << " " << (a ^ b) << " " << (~a) << " " << (a << 3) << " " << (a >> 2) << " " << (-17 >> 2) << "\n";
    int x = 10;
    x += 5; x -= 3; x *= 4; x /= 5; x %= 7;
    cout << x << "\n";
    cout << x++ << " " << ++x << " " << x-- << " " << --x << "\n";
    cout << (7 / 2) << " " << (7 / 2.0) << " " << (7 % 3) << " " << (1 / 3.0) << "\n";
    cout << (5 > 3) << (5 < 3) << (5 == 5) << (5 != 5) << (5 >= 5) << (5 <= 4) << "\n";
    cout << (true && false) << (true || false) << (!true) << "\n";
    return 0;
}
